/* Food: edible & toxic plants, gardening, cooking, preservation, hunting/fishing. */
(function () {
  function P(name, latin, o) {
    const ph = window.FG_PH ? window.FG_PH(latin, name) : '', lk = o.lookPh && window.FG_PH ? window.FG_PH(o.lookPh[0], o.lookPh[1]) : '';
    return `<div class="plant"><h3>${name} <span class="muted small" style="font-weight:400"><i>${latin}</i></span></h3>${ph && lk ? `<div class="photos2">${ph}${lk}</div>` : ph}<dl>
      <dt>Identify</dt><dd>${o.id}</dd><dt>Where</dt><dd>${o.where}</dd><dt>Season</dt><dd>${o.season}</dd><dt>Eat</dt><dd>${o.eat}</dd>
      ${o.look ? `<dt>⚠️ Lookalikes</dt><dd>${o.look}</dd>` : ''}${o.grow ? `<dt>🌱 Grow it</dt><dd>${o.grow}</dd>` : ''}</dl></div>`;
  }
  const RULES = `<div class="box danger"><b class="lbl">Foraging rules — never break these</b><ol style="margin:0">
<li><b>100% identification or don't eat it.</b> Use multiple features (leaves, stem, flowers, smell, habitat, season). If two sources disagree, don't eat it.</li>
<li>Learn the deadly lookalikes first (see <a href="#/a/plants/toxic">Poisonous plants</a>).</li>
<li>Try a small amount of any new wild food first and wait 24 hours — even edible plants can upset some people.</li>
<li>Avoid roadsides, ditches, railroad edges, power‑line corridors and lawns (herbicides, lead, exhaust) and polluted water.</li>
<li>Never eat wild mushrooms unless you are certain — a mistake can be fatal.</li></ol></div>`;
  (window.GUIDE = window.GUIDE || []).push(
{
  id: 'plants', title: 'Edible & Poisonous Plants', icon: '🌿', color: '#5f9e3f',
  blurb: 'Southeast wild foods, deadly lookalikes, seasons',
  intro: 'Wild plants are a <b>supplement</b>, not a full diet — most greens have very few calories. The best calorie sources are nuts (hickory, pecan, walnut, acorn), roots and tubers (cattail, groundnut), and fruits in season. Plant identification needs pictures — a printed field guide such as Peterson\'s <i>Edible Wild Plants</i> or a regional foraging book is worth packing.',
  articles: [
    { id: 'rules', title: 'Foraging safety & the edibility test', sum: 'How to forage without poisoning yourself', tags: ['foraging', 'universal edibility test', 'safety'], body: RULES + `
<h2>Universal Edibility Test (last resort only)</h2><p>Used by the U.S. military for unknown plants when starving and no ID is possible. It takes ~24 hours per plant part and <b>will not protect you from slow‑acting poisons</b> (e.g. some mushrooms, water hemlock acts fast). Never use it on mushrooms. In the Southeast there are enough known edibles that you should rarely need it.</p>
<ol class="steps"><li>Test only one part of one plant at a time. Don't eat anything for 8 hours before.</li><li>Smell it — strong almond (cyanide) or musty smells are bad signs.</li><li>Rub it on the inside of your wrist/elbow for 15 minutes; wait 8 hours for itch, burn or rash.</li><li>Touch to your lip for 3 minutes; then on the tongue for 15 minutes; then chew (don't swallow) for 15 minutes. Any burning, numbness, bitterness, soapiness → spit and stop.</li><li>Swallow a small amount (a teaspoon). Wait 8 hours, nothing else to eat.</li><li>If no reaction, eat ¼ cup prepared the same way; wait 8 hours. If still fine, it's probably safe as prepared.</li></ol>
<h2>General warning signs</h2><p>Be very cautious with plants that have: milky sap (exceptions: dandelion, chicory, wild lettuce), umbrella‑shaped flower clusters (carrot family — includes the deadliest plants), beans or seeds in pods (many toxic), bitter or soapy taste, three‑leaved growth pattern (poison ivy), white or yellow berries, almond scent in crushed leaves, grain heads with pink/purple/black spurs (ergot).</p>
<h2>Aggregate fruits are the safest beginner foods</h2><p>Blackberries, dewberries, raspberries, wineberries — there are <b>no poisonous lookalikes</b> to these "bumpy" berries in North America.</p>` },
    { id: 'greens', title: 'Wild greens & salad plants', sum: 'Dandelion, chickweed, plantain, purslane, wild onion & more', tags: ['dandelion', 'chickweed', 'plantain', 'purslane', 'wild onion', 'lambs quarters', 'violet', 'clover', 'henbit', 'wood sorrel', 'chicory', 'cleavers', 'amaranth', 'greens'], body: RULES + [
P('Dandelion', 'Taraxacum officinale', { id: 'Rosette of deeply toothed leaves ("lion\'s tooth"), <b>no hairs</b>, each yellow flower on its own hollow, leafless stem with milky sap.', where: 'Lawns, fields, disturbed ground everywhere.', season: 'Leaves best late winter–early spring (bitter later); flowers spring; roots fall–winter.', eat: 'Every part. Young leaves raw or cooked (boil once to reduce bitterness). Flowers raw, fried in batter, or made into tea. Roots roasted as coffee substitute. Rich in vitamins A, C, K.', look: 'Cat\'s ear and hawkweeds (hairy leaves, branched stems) — also edible. No dangerous lookalikes.' }),
P('Chickweed', 'Stellaria media', { id: 'Low, sprawling mats; small oval opposite leaves; tiny white star flowers with 5 deeply split petals (look like 10); a <b>single line of hairs</b> runs down one side of the stem.', where: 'Gardens, lawns, shady disturbed soil.', season: 'Cool season: fall through spring in the Southeast.', eat: 'Raw in salads, mild like spinach/corn silk. Cooked as a green.', look: '<b>Scarlet pimpernel</b> (toxic) has orange/red flowers and no hair line. Spurges have milky sap — avoid.' }),
P('Wild onion & wild garlic', 'Allium canadense, A. vineale', { id: 'Grass‑like or hollow round leaves, bulb at base, and <b>a strong onion/garlic smell when crushed</b>.', where: 'Lawns, fields, roadsides — extremely common in late winter.', season: 'Late fall through spring.', eat: 'Leaves and bulbs raw or cooked like scallions/chives. Bulblets at the top too.', look: '<b>Death camas</b> and <b>star‑of‑Bethlehem</b> look similar but have <b>NO onion smell</b> — they are toxic. "If it looks like an onion but doesn\'t smell like an onion, don\'t eat it." (Crush a fresh leaf each time — your hands can carry the smell.) <i>Nothoscordum</i> (false garlic, "crow poison") also lacks smell.' }),
P('Broadleaf & narrowleaf plantain', 'Plantago major, P. lanceolata', { id: 'Rosette of ribbed leaves with <b>parallel veins</b> that leave stringy threads when torn; slender seed spikes. (Not related to the banana‑like plantain.)', where: 'Lawns, paths, compacted soil everywhere.', season: 'Spring–fall; young leaves best.', eat: 'Young leaves raw or cooked (older ones stringy — chop). Seeds are edible (related to psyllium).', grow: 'Grows itself. Also a famous field <b>poultice</b>: chew a leaf and apply to bites, stings and splinters.' }),
P('Purslane', 'Portulaca oleracea', { id: 'Sprawling succulent with <b>smooth, reddish stems</b>, thick paddle‑shaped leaves, tiny yellow flowers. Clear (not milky) juice.', where: 'Gardens, sidewalk cracks, hot sunny disturbed soil.', season: 'Summer — thrives in Southeast heat.', eat: 'Raw (lemony, crunchy) or cooked. High in omega‑3 fats.', look: '<b>Spurges</b> (prostrate spurge) look similar but have thin stems and <b>milky white sap</b> — toxic. Snap a stem: purslane = clear, spurge = milky.' }),
P('Lamb\'s quarters', 'Chenopodium album', { id: 'Diamond/goose‑foot shaped leaves with a <b>white mealy powder</b> (especially on new growth) that water beads off. Up to 5 ft.', where: 'Gardens, farm fields, disturbed soil.', season: 'Spring–summer; seeds in fall.', eat: 'Leaves and tender tops cooked like spinach (better than spinach). Seeds edible like quinoa (rinse). Contains oxalates — cook, don\'t eat huge amounts raw.' }),
P('Amaranth / pigweed', 'Amaranthus spp.', { id: 'Alternate oval leaves, often with reddish stems and a fuzzy upper stem; dense bristly green or reddish flower spikes.', where: 'Fields and gardens.', season: 'Summer; seeds late summer–fall.', eat: 'Young leaves cooked; seeds are a nutritious grain (toast, boil or pop).' }),
P('Chicory', 'Cichorium intybus', { id: 'Rosette like dandelion but hairy; tall stiff branched stems with <b>sky‑blue flowers</b> that close by afternoon.', where: 'Roadsides, fields.', season: 'Leaves early spring; roots fall–winter.', eat: 'Young leaves cooked (bitter). Roasted root = famous coffee substitute (New Orleans coffee).' }),
P('Violets', 'Viola spp.', { id: 'Heart‑shaped, scalloped leaves; purple, white or yellow 5‑petal flowers with a spur.', where: 'Lawns, woods edges, shade.', season: 'Late winter–spring.', eat: 'Leaves and flowers raw or cooked; high in vitamin C. Leaves thicken soups.', look: 'African violet (houseplant) isn\'t a true violet. Don\'t confuse leaves with <b>lesser celandine</b> or <b>ground ivy</b> — check for the violet flower.' }),
P('Wood sorrel', 'Oxalis spp.', { id: 'Clover‑like with <b>3 heart‑shaped leaflets</b> that fold at night; yellow or pink 5‑petal flowers; seed pods like tiny okra.', where: 'Lawns, gardens, woods.', season: 'Spring–fall.', eat: 'Lemony leaves, flowers and pods raw as a nibble or seasoning. Oxalic acid — fine in moderation, not by the bowl.' }),
P('Clover', 'Trifolium spp.', { id: '3 oval leaflets often with a pale chevron; round white or red/pink flower heads.', where: 'Lawns, fields.', season: 'Spring–summer.', eat: 'Flowers raw or tea (red clover). Leaves better cooked (hard to digest raw). Dried flower heads ground into flour.' }),
P('Henbit & purple deadnettle', 'Lamium amplexicaule, L. purpureum', { id: 'Square stems (mint family), small scalloped leaves, small purple/pink tubular flowers. Henbit\'s upper leaves wrap the stem; deadnettle has purple‑tinged pointed top leaves.', where: 'Every lawn and field in late winter.', season: 'Late winter–spring.', eat: 'Leaves, stems and flowers raw or cooked. Mild. No stinging.' }),
P('Cleavers (bedstraw)', 'Galium aparine', { id: 'Weak, square stems covered in tiny hooks that <b>stick to clothing</b>; whorls of 6–8 narrow leaves.', where: 'Shady edges, thickets.', season: 'Early spring.', eat: 'Young shoots cooked as a green. Seeds roasted as a coffee substitute (it\'s related to coffee).' }),
P('Spiderwort', 'Tradescantia spp.', { id: 'Long grass‑like folded leaves; 3‑petaled blue/purple flowers; stems slimy when broken.', where: 'Woods edges, roadsides, gardens.', season: 'Spring–summer.', eat: 'Young leaves, stems and flowers raw or cooked.' }),
P('Sow thistle & wild lettuce', 'Sonchus, Lactuca spp.', { id: 'Dandelion‑like yellow flowers on branched stems; leaves clasp the stem; milky sap. Wild lettuce has a row of spines on the leaf midrib underside.', where: 'Fields, disturbed ground.', season: 'Spring.', eat: 'Young leaves cooked (bitter).' })
].join('') },
    { id: 'fruits', title: 'Wild fruits & berries', sum: 'Blackberries, muscadines, pawpaw, persimmon, mulberry, elderberry', tags: ['blackberry', 'dewberry', 'muscadine', 'scuppernong', 'wild grape', 'pawpaw', 'persimmon', 'mulberry', 'elderberry', 'plum', 'blueberry', 'huckleberry', 'maypop', 'passionflower', 'beautyberry', 'serviceberry', 'strawberry', 'saw palmetto', 'prickly pear', 'sumac', 'hackberry', 'berries', 'fruit'], body: RULES + [
P('Blackberry & dewberry', 'Rubus spp.', { id: 'Thorny arching canes (dewberry trails on the ground); leaves of 3–5 toothed leaflets; white 5‑petal flowers; aggregate berries red → black.', where: 'Fields, fence lines, clearings, everywhere.', season: 'Dewberries April–May; blackberries May–July.', eat: 'Raw, jam, cobbler, dried into fruit leather. Young peeled shoots edible. Leaf tea for diarrhea.', look: 'None dangerous — aggregate berries are the safest wild fruit. (Watch for chiggers, ticks and snakes in thickets.)' }),
P('Muscadine & scuppernong (wild grapes)', 'Vitis rotundifolia', { lookPh: ['Menispermum canadense', '⚠️ Canada moonseed — TOXIC lookalike'],  id: 'Woody climbing vine with tendrils; <b>round, coarsely toothed shiny leaves</b>; tight smooth bark (not shreddy); thick‑skinned purple or bronze grapes (scuppernong) in small clusters; 1–5 seeds per grape.', where: 'Forest edges, bottomlands throughout the Southeast.', season: 'August–October.', eat: 'Raw (pop the pulp, spit seeds), jelly, juice, wine, dried. Leaves edible cooked or wrapped like dolmas.', look: '<b>Canada moonseed (TOXIC, can kill)</b>: similar dark berries but <b>no tendrils</b>, leaves not toothed and attached to the stem inside the leaf edge, and each berry has a <b>single crescent‑moon shaped flat seed</b>. Porcelain berry (multicolored berries) — not edible. Virginia creeper (5 leaflets, blue berries on red stems) — toxic.', grow: 'Plant self‑fertile varieties (Carlos, Noble, Triumph). Needs sun and a trellis; nearly disease‑free in the South; long‑lived.' }),
P('Pawpaw', 'Asimina triloba', { id: 'Small understory tree, large drooping <b>oblong leaves</b> (6–12 in) that smell like green pepper when crushed; maroon bell flowers in spring; green potato‑shaped fruit in clusters.', where: 'Rich river bottoms and creek banks, often in patches. Not in south FL.', season: 'Late August–October; ripe when slightly soft and fragrant.', eat: 'Custard‑like tropical flavor (banana‑mango). Eat the pulp raw; <b>don\'t eat seeds or skin</b> (mildly toxic). Some people get stomach upset.', grow: 'Plant two different varieties for pollination; shade when young.' }),
P('American persimmon', 'Diospyros virginiana', { id: 'Tree with <b>blocky, "alligator‑hide" dark bark</b>; oval glossy leaves; orange 1–2 in fruit with a 4‑part cap.', where: 'Old fields, fence rows, woods edges.', season: 'September–February.', eat: '<b>Only when fully ripe</b> — wrinkled, mushy, often after frost or after falling. Unripe fruit is horribly astringent. Pulp for pudding, bread, fruit leather. Leaves make a vitamin C tea; roasted seeds a coffee substitute.' }),
P('Red mulberry', 'Morus rubra (and white mulberry M. alba)', { id: 'Tree with leaves that may be unlobed or mitten‑shaped/lobed on the same tree; milky sap in leaf stems; fruit looks like an elongated blackberry, attached to a little stem.', where: 'Woods edges, yards, fence lines.', season: 'May–July.', eat: 'Ripe fruit raw, jam, dried. <b>Unripe berries and leaves</b> can cause stomach upset/mild hallucinations — eat only ripe.' }),
P('Elderberry', 'Sambucus canadensis', { id: 'Shrub with compound leaves of 5–11 toothed leaflets, opposite; large flat clusters of tiny white flowers (June); drooping clusters of small dark purple berries; stems have white pith.', where: 'Wet ditches, stream sides, fence rows.', season: 'Flowers May–June; berries July–Sept.', eat: 'Berries <b>cooked</b> (jam, syrup, pie). Flowers in fritters or tea. Remove all stems.', look: '<b>Raw berries, stems, leaves and roots are toxic</b> (cyanide compounds). <b>Water hemlock</b> and <b>pokeweed</b> are deadly — learn them. Devil\'s walking stick (very thorny) and red elderberry (red fruit, mountains) — avoid.' }),
P('Wild plums (Chickasaw, American)', 'Prunus angustifolia, P. americana', { id: 'Thicket‑forming small trees, sometimes thorny twigs; white blossoms in early spring; small red/yellow plums.', where: 'Fence rows, old fields, sandy soil.', season: 'May–August.', eat: 'Fruit raw, jam, dried. <b>Don\'t eat pits, leaves or wilted leaves</b> (cyanide).' }),
P('Wild blueberries & huckleberries', 'Vaccinium, Gaylussacia spp.', { id: 'Shrubs with small oval leaves; bell/urn‑shaped white flowers; blue‑black berries with a <b>5‑pointed crown</b> on the bottom.', where: 'Acidic sandy pine woods, mountain balds, bogs.', season: 'May–August.', eat: 'Raw, dried, baked.', look: 'Check the crown and many small seeds. Avoid unknown blue berries without a crown.', grow: 'Rabbiteye blueberries (plant 2+ varieties) grow superbly in Southeast acidic soils; southern highbush for zones 8–10.' }),
P('Maypop (passionflower)', 'Passiflora incarnata', { id: 'Vine with 3‑lobed leaves and tendrils; spectacular purple fringed flowers; egg‑sized green fruit that <b>pops</b> when stepped on, turning yellow and wrinkled when ripe.', where: 'Sunny fields, fence rows, roadsides.', season: 'Fruit August–October.', eat: 'The pulp around the seeds when fruit is yellowish and wrinkly — tropical flavor. Leaves/flowers make a calming tea.' }),
P('Strawberry (wild)', 'Fragaria virginiana', { id: 'Three toothed leaflets on hairy stalks; white 5‑petal flowers; small red fruit with seeds in pits on the surface.', where: 'Fields, roadsides.', season: 'April–June.', eat: 'Raw. Leaf tea.', look: 'Mock strawberry (yellow flowers, bland fruit with seeds on the surface) — not harmful but tasteless.' }),
P('Serviceberry (sarvis)', 'Amelanchier spp.', { id: 'Small tree, smooth gray bark, white spring blossoms before leaves, red→purple berries with a crown like a blueberry.', where: 'Mountain and piedmont woods.', season: 'June.', eat: 'Raw, dried, baked. Very sweet.' }),
P('Prickly pear cactus', 'Opuntia humifusa', { id: 'Low cactus with flat green pads (nopales), yellow flowers, red/purple fruit (tunas). Has tiny hair‑like spines (glochids) as well as large spines.', where: 'Sandy coastal areas, dunes, dry fields throughout the Southeast.', season: 'Pads spring; fruit late summer–fall.', eat: 'Burn or scrape off spines and glochids (hold with tongs). Pads sliced and cooked like green beans; fruit raw or juiced (strain seeds).' }),
P('Saw palmetto', 'Serenoa repens', { id: 'Fan palm that grows low along the ground with saw‑toothed leaf stalks; clusters of olive‑sized berries turning black.', where: 'FL, coastal GA/SC/AL/MS pine flatwoods.', season: 'August–October.', eat: 'Ripe berries are edible but strongly flavored. Hearts of cabbage palm (<i>Sabal palmetto</i>) are edible but harvesting kills the tree — emergency use only.' }),
P('Sumac (red berries)', 'Rhus typhina, R. glabra, R. copallinum', { lookPh: ['Toxicodendron vernix', '⚠️ Poison sumac — white berries'],  id: 'Shrubs/small trees with compound leaves; <b>upright cone‑shaped clusters of fuzzy red berries</b>.', where: 'Old fields, roadsides, edges.', season: 'Late summer–fall.', eat: 'Soak clusters in <b>cold</b> water, strain through cloth → tart pink "sumac‑ade" (vitamin C). Dried berries as a lemony spice.', look: '<b>Poison sumac</b> has <b>white/grayish drooping berries</b> and grows in swamps — causes severe rash. Red upright berries = safe sumac.' }),
P('Hackberry & sugarberry', 'Celtis spp.', { id: 'Tree with warty, corky ridged bark; uneven leaf bases; small orange‑brown to purple berries with a thin sweet layer over a hard seed.', where: 'Bottomlands, fence rows, cities.', season: 'Fall through winter (stays on tree).', eat: 'Eat whole and crunch the seed, or pound berries and seeds together into a paste — surprisingly calorie‑rich.' }),
P('American beautyberry', 'Callicarpa americana', { id: 'Shrub with arching branches; opposite toothed leaves; <b>bright magenta berries clustered tightly around the stem</b>.', where: 'Pine woods, edges in the coastal plain.', season: 'August–November.', eat: 'Berries are edible in small amounts but bland; best cooked into jelly. Crushed leaves rubbed on skin repel mosquitoes and ticks (traditional, supported by USDA research).' })
].join('') },
    { id: 'nuts', title: 'Nuts, seeds & acorns', sum: 'Hickory, pecan, black walnut, acorns, chinquapin — calorie gold', tags: ['acorn', 'hickory', 'pecan', 'walnut', 'black walnut', 'chestnut', 'chinquapin', 'beech', 'pine nut', 'nuts', 'leaching', 'calories'], body: `<p>Nuts are the most important wild calorie source in the Southeast — 1 lb of shelled hickory nuts has ~3,000 calories. They store for months in the shell.</p>` + [
P('Acorns (oaks)', 'Quercus spp.', { id: 'Any oak. White oak group (rounded leaf lobes, acorns mature in 1 year) have less tannin than red oak group (pointed bristle‑tipped lobes).', where: 'Everywhere.', season: 'September–November.', eat: '<b>Must be leached</b> to remove bitter tannins. Shell, discard any with holes (weevils). Grind or chop, then: <b>cold leach</b> — soak in water, changing water 1–2× daily for days until not bitter (keeps starch for flour), or <b>hot leach</b> — boil, pour off brown water, repeat with fresh boiling water until not bitter. Use as flour (mix with wheat), porridge, or roasted.', look: 'Horse chestnut/buckeye nuts look like big shiny chestnuts without a cap — <b>toxic</b>. Acorns always have a scaly cap.' }),
P('Hickory nuts', 'Carya spp. (shagbark, mockernut, pignut)', { id: 'Compound leaves of 5–9 leaflets; nuts in a thick husk that splits into 4 sections; shagbark has peeling strips of bark.', where: 'Upland hardwood forests.', season: 'September–November.', eat: 'Crack with a rock, pick out meats; or crush whole nuts and boil — the oil and nut meats float, shells sink; skim for a rich "hickory milk" soup (traditional Cherokee <i>kanuchi</i>). Pignut can be bitter.' }),
P('Pecan', 'Carya illinoinensis', { id: 'Tall hickory with 9–17 slightly curved leaflets; elongated thin‑shelled nuts.', where: 'River bottoms, farms and yards across the Deep South.', season: 'October–December.', eat: 'Raw or roasted. Very high calorie and keeps for a year in the shell in cool storage.', grow: 'Needs space and decades, but a single tree feeds a family. Plant 2 varieties for pollination.' }),
P('Black walnut', 'Juglans nigra', { id: 'Compound leaves of 15–23 leaflets with a spicy smell; round green tennis‑ball husks that turn black; very hard ridged nut.', where: 'Bottomlands, fence rows, old homesites.', season: 'September–October.', eat: 'Remove husks (stains hands dark brown — wear gloves; drive over them on gravel), dry nuts 2 weeks, crack with a hammer/vise. Rich, strong flavor. Green husks crushed in water stun fish (illegal in most states).' }),
P('Chinquapin & American chestnut', 'Castanea pumila, C. dentata', { id: 'Shrubby trees with long, coarsely toothed leaves with bristle tips; nuts in <b>very spiny burs</b> (like sea urchins). Chinquapin: one small nut per bur.', where: 'Dry ridges and sandy woods; chestnut mostly root sprouts in the Appalachians (blight).', season: 'August–October.', eat: 'Sweet; raw, roasted or boiled.', look: '<b>Buckeye / horse chestnut</b> (toxic): smooth leathery husk (or only a few soft spines), palm‑like compound leaves with 5–7 leaflets. True chestnuts have <b>very sharp needle‑spined burs</b> and simple leaves.' }),
P('American beech', 'Fagus grandifolia', { id: 'Smooth gray "elephant skin" bark; toothed oval leaves that stay tan into winter; small triangular nuts in prickly husks.', where: 'Rich woods, slopes.', season: 'September–October.', eat: 'Nuts raw or roasted (eat in moderation raw).' }),
P('Pines', 'Pinus spp.', { id: 'Needles in bundles of 2–5.', where: 'Everywhere.', season: 'Year‑round.', eat: '<b>Needle tea</b> (chop green needles, steep in hot not boiling water 10 min) — vitamin C. Inner bark (cambium) can be eaten in starvation (strips, dried and ground). Young male pollen cones in spring. Southeast pines have tiny seeds — not worth it.', look: '<b>Yew</b> (flat single needles, red berry‑like cones; ornamental shrubs) is deadly. Avoid Norfolk Island "pine" (houseplant). Pregnant women should avoid pine needle tea.' })
].join('') },
    { id: 'roots', title: 'Roots, tubers & shoots', sum: 'Cattail, groundnut, kudzu, greenbrier, Jerusalem artichoke', tags: ['cattail', 'groundnut', 'kudzu', 'greenbrier', 'smilax', 'jerusalem artichoke', 'arrowhead', 'wapato', 'daylily', 'roots', 'tubers', 'poke'], body: RULES + [
P('Cattail', 'Typha spp.', { id: 'Tall flat sword leaves growing in water; brown "hot dog" seed head on a round stem in summer.', where: 'Marshes, ditches, pond edges everywhere.', season: 'Year‑round: shoots spring, green flower spikes early summer, pollen June, roots fall–winter.', eat: '"Supermarket of the swamp": peeled young shoots raw/cooked (cucumber‑like); green flower spikes boiled like corn on the cob; yellow pollen as flour; rhizomes (roots) crushed in water to release starch for flour. Fluff is excellent tinder and insulation.', look: '<b>Wild iris / yellow flag</b> (toxic) — similar flat leaves but grows in a fan, no brown seed head, and no cattail smell; check for old cattail seed heads nearby. Avoid polluted water — cattails absorb toxins.' }),
P('Groundnut (hopniss)', 'Apios americana', { id: 'Twining vine with 5–7 leaflet compound leaves; clusters of maroon/pink fragrant flowers in summer; underground "string of beads" tubers.', where: 'Moist thickets, stream banks.', season: 'Tubers fall–spring.', eat: 'Tubers <b>cooked</b> like potatoes (3× the protein of potatoes). Seeds/beans cooked. Some people are sensitive — try a small amount first.' }),
P('Kudzu', 'Pueraria montana', { lookPh: ['Toxicodendron radicans', '⚠️ Poison ivy — compare leaflets'],  id: 'Aggressive vine covering everything; 3 large leaflets (often lobed), hairy stems; purple grape‑scented flowers in late summer.', where: 'Everywhere in the Southeast — roadsides, forest edges.', season: 'Leaves & shoots spring–summer; flowers Aug–Sept; roots fall–winter.', eat: 'Young leaves and shoot tips cooked (or fried), flowers into jelly, huge roots pounded for starch (kudzu powder). Avoid areas sprayed with herbicide.', look: '<b>Poison ivy</b> also has 3 leaflets — kudzu leaflets are much larger, hairy, on a hairy vine. Check carefully.' }),
P('Greenbrier (catbrier)', 'Smilax spp.', { id: 'Green thorny vine with tendrils; shiny heart‑shaped leaves with parallel veins; blue‑black berries.', where: 'Everywhere — woods, thickets.', season: 'Spring–summer shoots.', eat: 'The tender growing tips (snap easily) raw or cooked — like asparagus. Roots of some species yield starch.' }),
P('Jerusalem artichoke (sunchoke)', 'Helianthus tuberosus', { id: 'Tall sunflower with small yellow flowers, rough sandpapery leaves; knobby tubers.', where: 'Fields, edges, moist soil.', season: 'Tubers after frost through winter.', eat: 'Tubers raw or cooked like potatoes. Contain inulin — can cause gas; long cooking helps.', grow: 'Plant a few tubers and you\'ll have them forever. Excellent survival crop.' }),
P('Arrowhead (duck potato)', 'Sagittaria spp.', { id: 'Arrowhead‑shaped leaves in shallow water; white 3‑petal flowers.', where: 'Marshes, pond edges.', season: 'Tubers fall–winter.', eat: 'Tubers at the end of roots in the mud (feel with your feet), cooked like potatoes.', look: 'Arrow arum (<i>Peltandra</i>) has similar leaves but net veins and causes intense mouth burning raw.' }),
P('Daylily', 'Hemerocallis fulva', { id: 'Clumps of long strap leaves; orange trumpet flowers that last one day; small tubers.', where: 'Old homesites, roadsides, ditches.', season: 'Shoots spring, buds/flowers summer.', eat: 'Young shoots, flower buds and flowers cooked. Small amounts at first — some people react.', look: '<b>True lilies (Lilium) and iris are toxic</b>. Daylily leaves all come from the base in a fan; lilies have leaves along the stem.' }),
P('Pokeweed (poke sallet) — DANGER', 'Phytolacca americana', { id: 'Big plant with smooth purple‑red stems, large leaves, and drooping clusters of dark purple berries.', where: 'Everywhere.', season: 'Young shoots in spring only.', eat: '<b>All parts are poisonous</b>, especially roots, berries and mature plants. A traditional Southern dish uses <i>only young leaves under ~8 in, with no red in the stem</i>, boiled in 2–3 changes of water. Mistakes cause severe vomiting and worse. <b>Not recommended</b> — listed so you recognize it and avoid the berries and roots.' })
].join('') },
    { id: 'mushrooms', title: 'Mushrooms: a few safer species', sum: 'Chanterelles, chicken of the woods, morels, puffballs — and why to be careful', tags: ['mushroom', 'chanterelle', 'morel', 'chicken of the woods', 'puffball', 'oyster', 'amanita', 'fungi'], body: `
<div class="box danger"><b class="lbl">Mushrooms can kill</b>Deadly Amanitas grow all over the Southeast and look like ordinary white or brown mushrooms. Mushrooms are low in calories — they're not worth the risk in survival. Only eat the distinctive species below if every feature matches, always cook them, and try a small amount first.</div>` + [
P('Chicken of the woods', 'Laetiporus spp.', { id: 'Bright orange shelves with yellow edges/undersides on trees and stumps (often oak); <b>no gills</b> (tiny pores underneath).', where: 'Hardwoods, summer–fall.', season: 'June–October.', eat: 'Tender outer edges, well cooked. Tastes like chicken. Avoid those growing on eucalyptus, yew or conifers; some people get stomach upset.', look: 'Few lookalikes; jack‑o\'‑lantern is orange but has gills.' }),
P('Chanterelles', 'Cantharellus spp.', { lookPh: ['Omphalotus illudens', '⚠️ Jack‑o’‑lantern — TOXIC lookalike'],  id: 'Egg‑yolk yellow/orange, vase shaped; underside has <b>blunt, forked false gills</b> (ridges) running down the stem; solid white flesh inside that pulls apart like string cheese; fruity apricot smell. Grow from the ground, single or scattered.', where: 'Hardwood and mixed woods after summer rains.', season: 'June–September.', eat: 'Cooked — excellent.', look: '<b>Jack‑o\'‑lantern</b> (toxic, severe vomiting): bright orange, grows in <b>clusters from wood or buried roots</b>, has <b>true sharp knife‑like gills</b>, orange flesh inside. <b>False chanterelle</b> has true crowded gills.' }),
P('Morels', 'Morchella spp.', { lookPh: ['Gyromitra esculenta', '⚠️ False morel — TOXIC'],  id: 'Honeycomb‑pitted cap; when sliced lengthwise the whole mushroom is <b>completely hollow</b> from cap tip to stem base, and the cap is attached directly to the stem.', where: 'Under dying elms, tulip poplars, old apple orchards, river bottoms.', season: 'March–April in the Southeast.', eat: 'Always cook thoroughly; raw morels are toxic.', look: '<b>False morels (Gyromitra)</b> — wrinkled brain‑like caps, <b>stuffed with cottony material</b> inside — can be deadly. <i>Verpa</i> (cap hangs free like a thimble) — avoid.' }),
P('Giant puffball', 'Calvatia spp.', { lookPh: ['Amanita bisporigera', '☠️ Destroying angel — DEADLY'],  id: 'Large white round ball (softball size and up), no stem/gills; inside <b>pure white and uniform like marshmallow/tofu</b>.', where: 'Fields, lawns, edges.', season: 'Late summer–fall.', eat: 'Slice and fry. Must be pure white inside.', look: '<b>Cut every one in half vertically</b>. If you see any outline of a cap, gills or stem inside, it\'s an Amanita "egg" — deadly. Earthballs (dark, firm purple‑black inside) are toxic.' }),
P('Oyster mushroom', 'Pleurotus ostreatus', { id: 'White/tan/gray shelf‑like clusters on dead hardwood; gills run down onto a short off‑center stem; white spore print; mild anise smell.', where: 'Dead hardwood logs, year‑round in cool weather.', season: 'Fall–spring.', eat: 'Cooked.', look: 'Angel wings (on conifers, thin) — avoid. Learn with an expert.', grow: 'Easiest mushroom to grow on straw or logs.' })
].join('') },
    { id: 'toxic', title: 'Poisonous plants of the Southeast', icon: '☠️', sum: 'Water hemlock, poison hemlock, jimsonweed, nightshade, poison ivy & more', tags: ['poisonous', 'toxic', 'water hemlock', 'poison hemlock', 'jimsonweed', 'nightshade', 'poison ivy', 'poison oak', 'poison sumac', 'oleander', 'manchineel', 'yew', 'castor bean', 'rosary pea', 'moonseed', 'buckeye', 'mountain laurel', 'rhododendron', 'carolina jessamine', 'death camas', 'lantana', 'foxglove'], body: `
<div class="box danger"><b class="lbl">Deadliest — learn these first</b></div>` + [
P('Water hemlock', 'Cicuta maculata', { id: 'Carrot family: <b>umbrella‑shaped clusters of small white flowers</b>, compound leaves with toothed leaflets whose <b>veins run to the notches</b> between teeth (not the tips); smooth hollow stems often purple‑streaked; root has <b>chambers</b> when cut lengthwise and oozes yellowish oily liquid.', where: 'Wet ground, ditches, stream banks — throughout the Southeast.', season: 'All year; flowers summer.', eat: '<b>The most toxic plant in North America.</b> A bite of root can kill within hours (violent seizures). Never eat any wild carrot‑family plant unless you are an expert.' }),
P('Poison hemlock', 'Conium maculatum', { id: 'Tall (3–8 ft) carrot‑family plant with fern‑like leaves, umbrella white flower clusters, <b>smooth hairless stems with purple blotches</b>, and a musty "mousy" smell.', where: 'Roadsides, ditches, fields (spreading in TN, KY, VA, NC).', season: 'Spring–summer.', eat: 'Deadly (killed Socrates). Wild carrot / Queen Anne\'s lace is similar but has <b>hairy</b> stems and smells like carrot — still, avoid if unsure.' }),
P('Jimsonweed', 'Datura stramonium', { id: 'Coarse plant with large toothed leaves, foul smell; big white/purple trumpet flowers; spiny seed pods.', where: 'Farm fields, disturbed ground.', season: 'Summer–fall.', eat: 'All parts toxic: hallucinations, delirium, high fever, death.' }),
P('Nightshades', 'Solanum spp.', { id: 'Star‑shaped white/purple flowers with yellow centers; black or orange/yellow berries (horse nettle has spiny stems and yellow tomato‑like fruit).', where: 'Fields, gardens, edges.', season: 'Summer–fall.', eat: 'Green/unripe berries and leaves toxic. Don\'t eat wild berries you can\'t identify. (Also: green potato skins and sprouts are mildly toxic.)' }),
P('Death camas & star‑of‑Bethlehem', 'Toxicoscordion, Ornithogalum', { id: 'Grass‑like leaves and bulbs like wild onion, but <b>no onion smell</b>.', where: 'Fields, lawns.', season: 'Spring.', eat: 'Toxic — can be fatal. Always smell‑test onions.' }),
P('Yew', 'Taxus spp.', { id: 'Evergreen shrub with <b>flat single needles</b> (dark above, pale below) and red fleshy berry‑like cups with a dark seed.', where: 'Ornamental plantings everywhere.', season: 'Year‑round.', eat: 'Needles and seeds can stop the heart. Don\'t make "pine" tea from it.' }),
P('Oleander', 'Nerium oleander', { id: 'Evergreen shrub with long narrow leathery leaves in whorls; pink/white/red clustered flowers.', where: 'Landscaping across FL and Gulf coast.', season: 'Year‑round.', eat: 'All parts deadly (heart). Don\'t use stems as skewers or burn it near food — smoke is toxic.' }),
P('Castor bean & rosary pea', 'Ricinus communis, Abrus precatorius', { id: 'Castor: large star‑shaped (palmate) leaves, spiny seed pods with mottled beans. Rosary pea: vine with bright <b>red seeds with a black spot</b>.', where: 'Castor: gardens, disturbed ground; rosary pea: central/south FL.', season: '—', eat: 'Seeds are extremely toxic if chewed (ricin, abrin).' }),
P('Manchineel', 'Hippomane mancinella', { id: 'Tree with shiny oval leaves and small green apple‑like fruit; often marked with red bands or warning signs.', where: 'Extreme south Florida & Keys coastline.', season: 'Year‑round.', eat: '"Little apple of death." Fruit is deadly; sap blisters skin; don\'t stand under it in rain or burn it.' }),
P('Buckeye / horse chestnut', 'Aesculus spp.', { id: 'Palm‑like compound leaves (5–7 leaflets); shiny brown nut with a pale "eye" in a smooth or slightly bumpy husk.', where: 'Woods throughout.', season: 'Fall.', eat: 'Toxic raw. Don\'t confuse with chestnuts (very spiny burs).' }),
P('Mountain laurel & rhododendron', 'Kalmia, Rhododendron spp.', { id: 'Evergreen shrubs with leathery leaves forming dense thickets in the mountains; showy pink/white/purple flowers.', where: 'Appalachians, piedmont.', season: 'Year‑round.', eat: 'Leaves, flowers and even honey from them are toxic.' }),
P('Carolina jessamine', 'Gelsemium sempervirens', { id: 'Vine with fragrant yellow trumpet flowers in late winter; opposite glossy leaves.', where: 'Everywhere in the coastal plain and piedmont.', season: 'Flowers Jan–April.', eat: 'All parts toxic (state flower of SC). Can be confused with honeysuckle — honeysuckle flowers are white/yellow, two‑lipped, and sweetly scented in summer.' }),
P('Lantana', 'Lantana camara', { id: 'Shrub with rough aromatic leaves and multicolored flower clusters; green berries turn blue‑black.', where: 'Landscapes, FL wild areas.', season: 'Year‑round in the south.', eat: 'Green berries toxic (especially to children and livestock).' })
].join('') + `
<h2>Poison ivy, oak & sumac</h2>
<div class="photos2">${window.FG_PH ? FG_PH('Toxicodendron radicans', 'Poison ivy') + FG_PH('Toxicodendron vernix', 'Poison sumac') : ''}</div>
<ul><li><b>Poison ivy:</b> "Leaves of three, let it be." 3 leaflets, middle one on a longer stalk; edges smooth or irregularly toothed; shiny or dull; hairy "rope" vines on trees; white berries. All parts, all year (even bare winter vines and smoke).</li><li><b>Poison oak (Atlantic):</b> 3 leaflets, lobed like oak leaves, fuzzy; sandy pinelands.</li><li><b>Poison sumac:</b> 7–13 smooth leaflets on red stems, white berries; swamps and wet areas.</li></ul>
<p><b>If exposed:</b> wash within 10–30 minutes with soap (dish soap, Tecnu, or Zanfel) and lots of cool water; scrub under nails; wash clothes and tools — the oil (urushiol) stays active for months. Rash appears in 12–72 hours: cool compresses, calamine, hydrocortisone, antihistamine for sleep. Jewelweed (orange "touch‑me‑not", often growing nearby) is a traditional remedy. Seek care if rash is on the face/eyes/genitals, widespread, or you inhaled smoke from burning plants.</p>
<p>Other skin irritants: stinging nettle (sting fades in an hour — nettles are edible cooked), trumpet creeper ("cow itch vine"), wild parsnip (sap + sunlight = burns), giant hogweed (rare).</p>` },
    { id: 'calendar', title: 'Foraging calendar (Southeast)', sum: 'What\'s in season each month', tags: ['calendar', 'season', 'month', 'when'], body: `
<div class="tbl"><table><tr><th>Season</th><th>Forage</th></tr>
<tr><td><b>Winter</b> (Dec–Feb)</td><td>Chickweed, wild onion/garlic, henbit, dandelion, violet leaves, cattail roots, persimmons (on ground), hackberries, Jerusalem artichoke tubers, groundnut, pine needle tea, oyster mushrooms. Acorns and hickory nuts stored from fall.</td></tr>
<tr><td><b>Early spring</b> (Mar–Apr)</td><td>Greens peak: dandelion, chickweed, cleavers, violets, plantain, wild lettuce, chicory, spiderwort. Redbud flowers (edible, pink, pea‑flavored), greenbrier tips, cattail shoots, ramps (mountains), morels, dewberries late April.</td></tr>
<tr><td><b>Late spring</b> (May–June)</td><td>Blackberries, dewberries, mulberries, wild strawberries, serviceberries, elderflowers, wild plums, blueberries, cattail flower spikes & pollen, lamb's quarters, kudzu shoots, daylily buds.</td></tr>
<tr><td><b>Summer</b> (Jul–Aug)</td><td>Blackberries, blueberries, huckleberries, elderberries, purslane, amaranth, maypop flowers, chanterelles, chicken of the woods, prickly pear pads, sumac berries, early muscadines.</td></tr>
<tr><td><b>Fall</b> (Sep–Nov)</td><td>Muscadines, pawpaws, persimmons, maypop fruit, beautyberries, acorns, hickory nuts, pecans, black walnuts, chinquapins, beech nuts, kudzu flowers, saw palmetto, prickly pear fruit, groundnuts, arrowhead tubers.</td></tr></table></div>` }
  ]
},
{
  id: 'garden', title: 'Growing Food', icon: '🌱', color: '#4f8f2f',
  blurb: 'Southeast gardening, crops, seeds, soil, small livestock',
  articles: [
    { id: 'start', title: 'Starting a survival garden', sum: 'Site, soil, beds, what to plant first', tags: ['garden', 'soil', 'raised bed', 'beginner', 'survival garden'], body: `
<p>The Southeast has a long growing season (200–300+ days) and two main seasons: <b>cool season</b> (fall–spring: greens, roots, cabbage family, peas, onions) and <b>warm season</b> (spring–fall: beans, peas, okra, sweet potatoes, squash, corn, tomatoes, peppers, melons). In Florida and the Gulf coast, fall and winter are the <i>best</i> garden seasons; mid‑summer heat stops many crops.</p>
<h2>Site</h2><ul><li>At least <b>6–8 hours of direct sun</b>.</li><li>Near water; away from big tree roots and black walnut trees (they poison tomatoes and others).</li><li>Good drainage — Southeast downpours drown roots. Use raised beds or mounded rows on clay.</li></ul>
<h2>Soil</h2><ul><li>Southeast soils are often red clay (piedmont) or sand (coastal plain) — both improve dramatically with <b>organic matter</b>: compost, aged manure, leaves, grass clippings.</li><li>Get a soil test (county extension office, cheap) — most Southeast soils are acidic and need lime (target pH 6.0–6.8, except blueberries 4.5–5.5).</li><li>Mulch 2–4 in deep with straw, leaves, or pine needles to hold moisture, stop weeds and keep soil cool.</li></ul>
<h2>Biggest‑payoff survival crops for the Southeast</h2><ol><li><b>Sweet potatoes</b> — calories, vitamins, edible leaves, store 6–12 months without refrigeration.</li><li><b>Southern peas (cowpeas)</b> — protein, drought & heat tolerant, dried peas store years; fix nitrogen.</li><li><b>Collards & kale</b> — greens almost all year.</li><li><b>Winter squash / Seminole pumpkin</b> — stores for months, vines resist pests.</li><li><b>Dry beans & field corn</b> — storable staples (corn + beans = complete protein).</li><li><b>Peanuts</b> — protein and fat; grow well in sandy soil.</li><li><b>Okra</b> — thrives in heat when nothing else produces.</li><li><b>Irish potatoes</b> — spring crop.</li><li><b>Perennials:</b> figs, muscadines, blueberries, pecans, pears, persimmons, Jerusalem artichokes, asparagus, chaya (FL).</li></ol>
<p>Use the <a href="#/tools/planting">planting calendar</a> for dates based on your frost dates.</p>
<h2>How much to plant?</h2><p>Feeding one adult entirely from a garden takes roughly 1/10 to ¼ acre with calorie crops (sweet potatoes, potatoes, beans, corn, peanuts). Start smaller: a 10×20 ft bed of sweet potatoes can yield 100–200 lb.</p>` },
    { id: 'crops', title: 'Crop growing guide', sum: 'How to grow the key Southeast crops', tags: ['sweet potato', 'tomato', 'beans', 'peas', 'okra', 'corn', 'squash', 'collards', 'potatoes', 'peanuts', 'onions', 'garlic', 'crops'], body: `
<div class="tbl"><table><tr><th>Crop</th><th>Plant</th><th>Spacing</th><th>Notes</th></tr>
<tr><td><b>Sweet potatoes</b></td><td>Slips 2–4 wks after last frost when soil 65°F+</td><td>12–18 in in rows 3–4 ft apart, on ridges</td><td>Grow slips: half‑submerge a sweet potato in water in a sunny window; snap off 6–8 in sprouts and root them in water. Harvest before frost at 90–120 days; <b>cure</b> 7–10 days at 80–85°F humid, then store at 55–60°F. Leaves are edible cooked.</td></tr>
<tr><td><b>Southern peas</b></td><td>Direct seed when soil is warm (May–July)</td><td>3–4 in, rows 3 ft</td><td>No fertilizer needed. Pick green for fresh shelling or leave to dry on vine. Iron & Clay, Pinkeye Purple Hull, Zipper Cream.</td></tr>
<tr><td><b>Bush/pole beans</b></td><td>After last frost; again late summer</td><td>3–4 in; poles 6 in</td><td>Pole beans produce longer. Let some dry for seed and dried beans.</td></tr>
<tr><td><b>Tomatoes</b></td><td>Transplants after frost; fall crop in July–Aug (Deep South)</td><td>2–3 ft, staked or caged</td><td>Choose heat‑setting and disease‑resistant types. Mulch, water at the base, remove lower leaves to prevent blight. Cherry tomatoes are most reliable.</td></tr>
<tr><td><b>Peppers</b></td><td>Transplants 2 weeks after frost</td><td>18 in</td><td>Hot peppers thrive; dry them for storage.</td></tr>
<tr><td><b>Okra</b></td><td>Direct seed when soil is warm</td><td>12–18 in</td><td>Soak seeds overnight. Harvest every day or two.</td></tr>
<tr><td><b>Corn</b></td><td>After frost</td><td>8–12 in, blocks of 4+ rows</td><td>Heavy feeder (needs nitrogen). Dent/flint corn for cornmeal and storage (Hickory King, Bloody Butcher, Truckers Favorite).</td></tr>
<tr><td><b>Squash</b></td><td>After frost; again late summer</td><td>3–4 ft</td><td>Vine borers kill summer squash in the South — plant succession crops, or grow <i>C. moschata</i> types (butternut, Seminole pumpkin, tromboncino) which resist borers.</td></tr>
<tr><td><b>Collards/kale/cabbage</b></td><td>Fall (Aug–Oct) and late winter</td><td>18–24 in</td><td>Pick lower leaves continuously. Cabbage worms: hand pick or Bt spray.</td></tr>
<tr><td><b>Turnips & mustard</b></td><td>Late summer–fall; late winter</td><td>Thin to 4 in</td><td>Fast, two crops (roots + greens).</td></tr>
<tr><td><b>Irish potatoes</b></td><td>Late winter (Feb–Mar), 2–4 weeks before last frost</td><td>12 in, rows 3 ft</td><td>Cut seed potatoes to 2 eyes each, let dry a day. Hill soil around plants. Harvest when tops die.</td></tr>
<tr><td><b>Onions</b></td><td>Short‑day transplants Oct–Feb (South), sets in spring</td><td>4 in</td><td>Use short‑day varieties in the Deep South (Granex, Texas Grano); intermediate north of ~35°N.</td></tr>
<tr><td><b>Garlic</b></td><td>Oct–Nov</td><td>6 in</td><td>Softneck & Creole types do best in the South. Harvest late May–June.</td></tr>
<tr><td><b>Peanuts</b></td><td>2–3 wks after frost, soil 65°F+</td><td>6–8 in</td><td>Loose sandy soil. Dig when leaves yellow (110–150 days), dry on plants 2 weeks.</td></tr>
<tr><td><b>Greens (lettuce, spinach)</b></td><td>Fall and late winter</td><td>Thin to 6–8 in</td><td>Bolts in heat; shade cloth extends season.</td></tr></table></div>
<h2>Three Sisters</h2><p>Native American method: plant corn in hills; when 6 in tall, plant pole beans around it (climb the corn, add nitrogen); plant squash between hills (shades out weeds). Works well in the Southeast with field corn and cowpeas or runner beans.</p>` },
    { id: 'seeds', title: 'Seeds: saving, storing, starting', sum: 'Heirlooms vs hybrids, seed saving, germination', tags: ['seeds', 'seed saving', 'heirloom', 'germination', 'seed storage'], body: `
<ul><li><b>Open‑pollinated / heirloom</b> seeds grow true from saved seed. <b>Hybrids (F1)</b> don't — buy heirlooms for long‑term self‑sufficiency.</li><li>Store seeds cool, dry and dark: paper envelopes in a sealed jar with a desiccant pack, in the fridge or a cool closet. Most seeds last 3–5 years; onions, parsnips and corn only 1–2.</li><li>Germination test: roll 10 seeds in a damp paper towel in a bag; count sprouts after a week.</li></ul>
<h2>Easy seeds to save</h2><ul><li><b>Beans & peas:</b> let pods dry brown on the plant; shell and dry more. Self‑pollinating — easy.</li><li><b>Tomatoes:</b> scoop seeds and pulp into a jar with water, let ferment 3 days, rinse, dry on a plate.</li><li><b>Peppers:</b> seeds from fully ripe (red) fruit, dry them. Separate varieties to avoid crossing.</li><li><b>Squash/pumpkins:</b> from fully mature fruit; will cross with others of the same species — grow one variety per species or hand‑pollinate.</li><li><b>Lettuce, okra, sunflowers, corn</b> (corn needs 100+ plants to avoid inbreeding).</li></ul>
<h2>Starting seeds</h2><p>Use clean containers with drainage, seed‑starting mix, sow 2–3× as deep as the seed is wide, keep moist and warm. Bright light (a sunny window or cheap LED shop light 2–4 in above seedlings). "Harden off" seedlings by putting them outside a few hours a day for a week before transplanting.</p>` },
    { id: 'compost', title: 'Compost, fertilizer & water', sum: 'Making compost, natural fertilizers, watering & rainwater', tags: ['compost', 'fertilizer', 'manure', 'watering', 'irrigation', 'rain barrel', 'mulch'], body: `
<h2>Compost</h2><ul><li>Mix about 3 parts "browns" (dry leaves, straw, cardboard, sawdust) to 1 part "greens" (kitchen scraps, grass clippings, fresh manure, weeds without seeds).</li><li>Keep it as moist as a wrung‑out sponge; turn every week or two. Ready in 2–6 months in Southeast heat.</li><li>No meat, dairy, oils, pet/human waste, or diseased plants in a home pile.</li></ul>
<h2>Natural fertilizers</h2><ul><li>Aged manure (chicken = strong nitrogen; rabbit can go straight on the garden).</li><li>Wood ash: potassium and raises pH — use lightly; not for blueberries or potatoes.</li><li>Diluted urine (1:10 with water): nitrogen; apply to soil, not leaves.</li><li>Comfrey or grass "tea": steep in water for 2 weeks.</li><li>Legumes (peas, beans, clover) add nitrogen to soil for the next crop.</li></ul>
<h2>Watering</h2><ul><li>About 1 inch of water per week (more in sandy soil and summer heat). Water deeply and less often, early morning, at the base.</li><li>Drip lines and soaker hoses cut water use 50%.</li><li>Rain barrel: 1 inch of rain on 1,000 sq ft of roof ≈ 600 gallons. Use a first‑flush diverter and screen mosquitoes out.</li><li>Ollas (unglazed clay pots buried and filled with water) slowly irrigate roots.</li></ul>` },
    { id: 'pests', title: 'Pests & diseases (organic)', sum: 'Common Southeast garden pests and fixes', tags: ['pests', 'aphids', 'hornworm', 'squash bug', 'vine borer', 'blight', 'nematodes', 'organic'], body: `
<div class="tbl"><table><tr><th>Problem</th><th>Fix</th></tr>
<tr><td>Aphids</td><td>Spray off with water; insecticidal soap; encourage ladybugs.</td></tr>
<tr><td>Tomato hornworm</td><td>Hand‑pick (big green caterpillars); leave ones covered in white wasp cocoons. Bt spray.</td></tr>
<tr><td>Cabbage worms/loopers</td><td>Hand‑pick, Bt spray, row covers.</td></tr>
<tr><td>Squash vine borer</td><td>Wilting squash with sawdust holes at base: slit stem, remove grub, bury stem. Plant moschata squash; row covers until flowering.</td></tr>
<tr><td>Squash bugs, stink bugs</td><td>Hand pick eggs (bronze clusters under leaves) and adults into soapy water.</td></tr>
<tr><td>Fire ants</td><td>Boiling water on mounds; spinosad baits.</td></tr>
<tr><td>Root‑knot nematodes (sandy soils)</td><td>Rotate crops; plant marigolds/sunn hemp as cover; choose "N" resistant varieties; solarize soil with clear plastic in summer.</td></tr>
<tr><td>Early blight / leaf spots</td><td>Mulch, water at base, remove lower leaves, space plants for airflow; rotate crops.</td></tr>
<tr><td>Powdery mildew</td><td>1 tbsp baking soda + few drops soap per gallon water spray; milk spray 1:9.</td></tr>
<tr><td>Deer & rabbits</td><td>Fencing (8 ft for deer, or double fences), dogs, motion sprinklers.</td></tr>
<tr><td>Birds</td><td>Netting over berries and seedlings.</td></tr></table></div>
<p>Rotate plant families each season (tomato family, squash family, cabbage family, beans) to prevent soil diseases.</p>` },
    { id: 'containers', title: 'Container, bucket & small-space gardening', sum: 'Grow food on a porch or in a car-camp situation', tags: ['container', 'bucket', 'small space', 'balcony', 'microgreens', 'sprouts'], body: `
<ul><li>5‑gallon buckets (drill drainage holes) grow 1 tomato, 2 peppers, 3–5 potato plants, or a bunch of greens.</li><li>Fabric grow bags drain well and keep roots cooler.</li><li>Use potting mix (not garden soil) and add compost; containers dry quickly in Southeast heat — water daily in summer.</li><li>Best container crops: cherry tomatoes, peppers, greens, herbs, bush beans, green onions, sweet potatoes (beautiful vines).</li></ul>
<h2>Sprouts (no soil, 3–5 days)</h2><p>Soak 2 tbsp of seeds (alfalfa, mung beans, lentils, broccoli, radish) overnight in a jar, drain, rinse twice a day, keep out of direct sun. Ready in 3–5 days — fresh vitamins anywhere, even in a car. Use only seeds sold for sprouting (not treated garden seed).</p>
<h2>Microgreens</h2><p>Sow seeds thickly on 1 in of soil in a tray; harvest in 7–14 days.</p>` },
    { id: 'perennials', title: 'Fruit trees & perennial food plants', sum: 'Plant once, harvest for decades', tags: ['fruit tree', 'fig', 'pear', 'apple', 'citrus', 'blueberry', 'perennial', 'asparagus', 'orchard'], body: `
<div class="tbl"><table><tr><th>Plant</th><th>Zones</th><th>Notes</th></tr>
<tr><td>Fig</td><td>7–10</td><td>Easiest Southern fruit. Celeste, Brown Turkey, LSU varieties. Root cuttings easily.</td></tr>
<tr><td>Muscadine grape</td><td>7–10</td><td>Disease free, huge yields. Self‑fertile types.</td></tr>
<tr><td>Rabbiteye blueberry</td><td>7–9</td><td>Plant 2+ varieties; acidic soil.</td></tr>
<tr><td>Asian & Southern pears</td><td>6–9</td><td>Kieffer, Orient, Moonglow resist fire blight.</td></tr>
<tr><td>Persimmon (Asian/American)</td><td>6–10</td><td>Almost no pests.</td></tr>
<tr><td>Pecan</td><td>6–9</td><td>Long term calorie bank.</td></tr>
<tr><td>Pawpaw</td><td>5–8</td><td>Native, shade tolerant.</td></tr>
<tr><td>Citrus (satsuma, kumquat, Meyer lemon)</td><td>8b–10</td><td>Satsumas tolerate brief freezes to ~20°F.</td></tr>
<tr><td>Loquat</td><td>8–10</td><td>Fruits in early spring.</td></tr>
<tr><td>Peaches/plums</td><td>6–9</td><td>Choose low‑chill varieties in the Deep South; need spraying.</td></tr>
<tr><td>Apples</td><td>6–8</td><td>Low‑chill types (Anna, Dorsett) in FL; heirloom Southern apples in mountains.</td></tr>
<tr><td>Blackberries (thornless)</td><td>6–9</td><td>Fruit in 2 years.</td></tr>
<tr><td>Asparagus</td><td>6–8</td><td>20+ years of spring spears.</td></tr>
<tr><td>Chaya, moringa, cassava</td><td>9–10</td><td>Tropical perennials for FL — must be cooked (chaya, cassava contain cyanide compounds).</td></tr></table></div>` },
    { id: 'livestock', title: 'Chickens, rabbits & small livestock', sum: 'Eggs and meat on a small scale', tags: ['chickens', 'eggs', 'rabbits', 'goats', 'livestock', 'quail', 'bees'], body: `
<h2>Chickens</h2><ul><li>3–5 hens = 2–4 eggs a day for a family. No rooster needed for eggs.</li><li>Need: secure coop (4 sq ft/bird inside, 10 outside), roosts, nest box (1 per 4 hens), predator‑proof hardware cloth (raccoons, foxes, hawks, snakes).</li><li>Feed: layer feed + kitchen scraps + foraging. Oyster shell for calcium.</li><li>Heat: provide shade and water in summer; heat‑tolerant breeds (Leghorn, Rhode Island Red, Easter Egger, Plymouth Rock).</li><li>Unwashed eggs keep weeks on the counter; months in the fridge or water‑glassed (pickling lime solution).</li></ul>
<h2>Rabbits</h2><p>Quiet, efficient meat: one doe can produce 50+ lb of meat per year. Need shade (they die in heat above 90°F — frozen water bottles help), wire cages, hay and pellets or forage. Manure goes directly on the garden.</p>
<h2>Quail</h2><p>Coturnix quail lay at 7 weeks, need little space, eggs and meat.</p>
<h2>Bees</h2><p>Honey (never spoils), wax, and better garden pollination. Requires learning; local beekeeping clubs help.</p>
<p>Check local ordinances before keeping animals.</p>` }
  ]
},
{
  id: 'cooking', title: 'Off-Grid Cooking', icon: '🍳', color: '#d98a41',
  blurb: 'Fire, Dutch oven, rocket stove, recipes from basics',
  articles: [
    { id: 'methods', title: 'Ways to cook without power', sum: 'Campfire, coals, Dutch oven, camp stoves, solar, retained heat', tags: ['cooking', 'campfire', 'dutch oven', 'camp stove', 'rocket stove', 'solar oven', 'haybox', 'thermal cooking', 'butane', 'propane'], body: `
<ul>
<li><b>Camp stoves:</b> propane (Coleman 2‑burner) or butane single burner — easiest. <b>Outdoors only</b> (or a well‑ventilated area for butane stoves rated for indoor use). A 1‑lb propane bottle runs ~1–2 hours on high.</li>
<li><b>Coals, not flames:</b> cook over a bed of glowing hardwood coals — even heat, less burning. Rake coals to one side and keep a fire burning on the other to make more.</li>
<li><b>Grill grate</b> over rocks or a fire pit; foil packets in coals (20–30 min for vegetables/fish).</li>
<li><b>Dutch oven</b> (cast iron with a lipped lid): bake, roast, stew, fry over coals. See <a href="#/tools/dutch">coal calculator</a>.</li>
<li><b>Rocket stove</b> — burns twigs very efficiently. See <a href="#/a/make/rocket-stove">build one</a>.</li>
<li><b>Solar oven</b> — 250–350°F on sunny days; perfect for beans, rice, stews. See <a href="#/a/make/solar-oven">build one</a>.</li>
<li><b>Retained‑heat (haybox/thermal) cooking:</b> bring food to a boil for 5–15 minutes, then put the covered pot in an insulated box (sleeping bag, cooler packed with towels, hay). It keeps cooking for hours with no fuel — saves 50–70% fuel for rice, beans, stews, oatmeal.</li>
<li><b>Car engine cooking:</b> foil‑wrapped food on a hot engine block cooks while driving (secure it!).</li>
<li><b>Spit roasting and stick cooking:</b> green hardwood stick (not toxic species — avoid oleander, yew).</li>
</ul>
<h2>Fuel‑saving tips</h2><ul><li>Lids on pots; windscreens around stoves.</li><li>Soak beans/rice/pasta before cooking.</li><li>Cut food small. Pressure cookers cut fuel use dramatically.</li></ul>` },
    { id: 'staples', title: 'Survival staples: bread & basics', sum: 'Bannock, hardtack, cornbread, hoecakes, biscuits, tortillas', tags: ['bannock', 'hardtack', 'cornbread', 'hoecake', 'biscuits', 'tortillas', 'bread', 'recipes', 'flatbread', 'ash cake'], body: `
<h3>Bannock (frontier skillet bread)</h3><p>2 cups flour · 1 tbsp baking powder · ½ tsp salt · 2 tbsp fat (oil, lard, butter) · ~¾ cup water. Mix dry, cut in fat, add water to make a soft dough. Pat into a ¾‑in round in a greased skillet over low coals, 10–15 min per side, or wrap thick "snakes" of dough around a green stick and toast over coals. Add dried fruit, sugar, cheese, or wild berries.</p>
<h3>Hardtack (keeps for years)</h3><p>2 cups flour · ½–¾ cup water · 1 tsp salt. Stiff dough, roll ½ in thick, cut 3‑in squares, poke 16 holes in each. Bake 30 min per side at 375°F (or long and slow in a Dutch oven); then dry completely. Store airtight. Soak in coffee, soup or water before eating, or fry in fat.</p>
<h3>Hoecakes / johnnycakes</h3><p>1 cup cornmeal · ½ tsp salt · about 1 cup boiling water (or milk) · 1 tbsp fat. Mix to a thick batter, drop spoonfuls on a hot greased skillet (or hoe blade!), flatten, cook until crisp both sides.</p>
<h3>Skillet cornbread</h3><p>Heat a cast iron skillet with 2 tbsp fat. Mix 1½ cups cornmeal, ½ cup flour, 1 tbsp baking powder, 1 tsp salt, 1 egg (or 1 tbsp powdered egg + water), 1½ cups milk/buttermilk (powdered milk works). Pour into the hot skillet; bake in a Dutch oven ~20–25 min.</p>
<h3>Ash cake</h3><p>Make a stiff cornmeal or flour dough, wrap in wet leaves (corn husks, grape or collard leaves — non‑toxic), and bury in hot ashes/coals 15–20 min.</p>
<h3>Pan biscuits</h3><p>2 cups flour · 1 tbsp baking powder · 1 tsp salt · ⅓ cup shortening/lard · ¾ cup milk. Cut fat into flour, stir in milk, pat out, cut biscuits; bake in a Dutch oven (≈425°F, 12–15 min) or cook covered in a greased skillet on low coals, flipping once.</p>
<h3>Flour tortillas</h3><p>2 cups flour · 1 tsp salt · ¼ cup fat · ¾ cup warm water. Knead, rest 15 min, divide into 8 balls, roll thin, cook on a dry hot skillet 30–60 sec per side.</p>
<h3>Sourdough starter</h3><p>Mix equal weights flour and water in a jar, cover loosely. Feed daily (discard half, add fresh flour + water). Bubbly and doubling in 5–10 days. Lets you bake bread with no yeast or baking powder.</p>` },
    { id: 'meals', title: 'Hearty meals from storage & the wild', sum: 'Beans & rice, grits, stews, fish, game, wild greens', tags: ['beans', 'rice', 'grits', 'stew', 'squirrel', 'rabbit', 'fish', 'recipes', 'greens', 'pot likker', 'hoppin john', 'meals'], body: `
<h3>Beans & rice / Hoppin' John</h3><p>Soak 1 lb dry beans or black‑eyed peas overnight (or boil 2 min and soak 1 hour). Simmer in fresh water with onion, salt, and smoked meat or bacon 1–2 hours until tender (black‑eyed peas ~45 min). Serve over rice (1 part rice : 2 parts water, simmer covered 18 min). Beans + rice/corn = complete protein. Retained‑heat cooking saves fuel.</p>
<h3>Grits</h3><p>1 cup grits to 4 cups water + 1 tsp salt. Boil, stir in grits slowly, simmer covered, stirring often, 5 min (quick) to 45 min (stone‑ground). Add fat, cheese, or eggs.</p>
<h3>Mess of greens (collards, wild greens)</h3><p>Wash well, strip tough stems, chop. Simmer with onion, smoked meat or a little fat, salt, a splash of vinegar, and pepper flakes 30–60 min. Drink the "pot likker" — it's full of vitamins.</p>
<h3>Camp stew / Brunswick‑style</h3><p>Brown any meat (squirrel, rabbit, chicken, canned meat). Add water, onions, potatoes, canned tomatoes, corn, beans, salt and pepper. Simmer until meat falls from bones (squirrel/rabbit: 1.5–2 hours).</p>
<h3>Fried fish</h3><p>Scale and gut (or fillet). Dredge in seasoned cornmeal; fry in ½ in of hot oil (350°F — a cornmeal pinch sizzles immediately) 2–4 min per side until flaky. Or cook on a plank, on a stick, or in foil with lemon/wild onion.</p>
<h3>Small game</h3><p>Squirrel and rabbit are lean — braise, stew, or fry (parboil older animals first). Cook wild meat well done: <b>165°F</b> for small game and birds, <b>160°F</b> for wild hog and ground meat. Wear gloves when cleaning rabbits (tularemia).</p>
<h3>Emergency "everything" soup</h3><p>Rice or pasta + canned meat + canned veggies + bouillon + wild greens (dandelion, chickweed, wild onion). Stretch with extra water and flour/cornmeal to thicken.</p>
<h3>Acorn mush / pancakes</h3><p>Leached acorn meal (see <a href="#/a/plants/nuts">Nuts</a>) mixed half and half with flour or cornmeal for pancakes and bread.</p>
<h3>Cattail pollen pancakes</h3><p>Replace up to half the flour in any pancake recipe with sifted yellow cattail pollen.</p>
<h3>Wild drinks</h3><p>Pine needle tea (vitamin C), sumac‑ade, sassafras root tea (traditional; contains safrole — occasional only), mint, spicebush twig tea, chicory/dandelion coffee, sun tea.</p>` },
    { id: 'safety', title: 'Food safety without refrigeration', sum: 'Danger zone, power outage rules, spoiled food signs', tags: ['food safety', 'spoiled', 'refrigerator', 'power outage', 'danger zone', 'botulism', 'cooler'], body: `
<ul><li><b>Danger zone 40–140°F:</b> bacteria double every 20 minutes. Perishables left in the zone more than 2 hours (1 hour above 90°F) should be thrown out.</li><li>Without power: a closed fridge stays cold ~4 hours; full freezer ~48 hours (half full 24 h). Put a thermometer in both.</li><li>Food in a freezer with ice crystals or ≤40°F can be refrozen.</li><li>Coolers: block ice lasts longer than cubes; pre‑chill; keep in shade; drain meltwater sparingly; don't open often. Use separate coolers for drinks and food.</li><li>Cook meats to safe temperatures: poultry & wild game birds 165°F, ground meat & wild hog 160°F, whole cuts of beef/venison 145°F with rest.</li><li>Leftovers: eat immediately or keep hot (above 140°F); otherwise discard.</li><li><b>Throw out</b> cans that are bulging, leaking, deeply dented on seams, rusted through, or spurt when opened — botulism risk. Never taste to test.</li><li>When in doubt, throw it out.</li></ul>
<h2>Foods that need no refrigeration</h2><p>Canned meats/fish/beans/vegetables/fruit, peanut butter, nuts, crackers, tortillas, rice, oats, pasta, grits, dried fruit, jerky, hard cheeses (days), unwashed eggs (weeks in cool temps), honey, powdered milk, shelf‑stable milk, potatoes, onions, sweet potatoes, winter squash, apples, citrus.</p>` }
  ]
},
{
  id: 'preserve', title: 'Food Preservation & Storage', icon: '🫙', color: '#b07a35',
  blurb: 'Canning, drying, smoking, salting, root cellars, storage life',
  articles: [
    { id: 'storage', title: 'Long-term food storage', sum: 'What to store, shelf life, containers, rotation', tags: ['food storage', 'shelf life', 'mylar', 'bucket', 'rice', 'beans', 'stockpile', 'pantry'], body: `
<p>"Store what you eat, eat what you store." Rotate first‑in‑first‑out.</p>
<div class="tbl"><table><tr><th>Food</th><th>Shelf life (cool, dry, sealed)</th></tr>
<tr><td>White rice, dry beans, wheat berries, rolled oats, sugar, salt, honey</td><td>10–30 years in Mylar + oxygen absorbers</td></tr>
<tr><td>Freeze‑dried meals</td><td>25 years (unopened)</td></tr>
<tr><td>Canned foods</td><td>2–5 years (high‑acid tomato/fruit 12–18 months for best quality); often safe much longer if cans are sound</td></tr>
<tr><td>Pasta, white flour</td><td>1–2 years (much longer in Mylar)</td></tr>
<tr><td>Cornmeal, brown rice, whole wheat flour, nuts</td><td>6–12 months (oils go rancid) — freeze to extend</td></tr>
<tr><td>Peanut butter</td><td>1–2 years unopened</td></tr>
<tr><td>Powdered milk</td><td>2–20 years depending on type and packaging</td></tr>
<tr><td>MREs</td><td>~3 years at 80°F, 5 years at 70°F; much shorter in a hot car</td></tr>
<tr><td>Cooking oil</td><td>1–2 years; coconut oil and ghee longer</td></tr></table></div>
<h2>Packaging</h2><ul><li>Food‑grade 5‑gal buckets with gasket lids (Gamma lids), lined with 5‑mil Mylar bags.</li><li>Oxygen absorbers: ~2,000 cc per 5‑gal bucket of grain. Seal the Mylar with a hot iron.</li><li>Keep storage <b>cool</b> — every 18°F higher halves shelf life. Avoid garages and attics in the Southeast summer. Interior closets are best.</li><li>Keep off concrete floors; protect from rodents and pantry moths (freeze grains 3 days before storing kills insect eggs).</li></ul>
<h2>Basic one‑person‑year (classic LDS guideline)</h2><p>300 lb grains (wheat, rice, oats, corn), 60 lb legumes, 16 lb powdered milk, 10 qt oil, 60 lb sugar/honey, 8 lb salt, plus vitamins, seasonings and variety. A car‑based kit realistically holds 1–4 weeks of food.</p>` },
    { id: 'canning', title: 'Canning safely', sum: 'Water bath vs pressure canning, botulism prevention', tags: ['canning', 'pressure canner', 'water bath', 'jars', 'botulism', 'tomatoes', 'pickles'], body: `
<div class="box danger"><b class="lbl">Botulism rule</b><b>Low‑acid foods</b> — vegetables (except pickled), beans, meats, fish, soups, and mixtures — <b>must be pressure canned</b> (240°F). A boiling water bath can't kill botulism spores in these foods. Follow tested recipes (USDA Complete Guide to Home Canning, Ball Blue Book).</div>
<h2>Water bath canning (high‑acid foods)</h2><p>Fruits, jams, jellies, pickles, salsa with tested acid, tomatoes <i>with added lemon juice or citric acid</i> (2 tbsp bottled lemon juice per quart).</p>
<ol class="steps"><li>Wash jars, keep hot. New flat lids; rings can be reused.</li><li>Fill hot food, leave headspace (¼ in jams, ½ in fruits/tomatoes). Remove air bubbles, wipe rims, fingertip‑tight rings.</li><li>Lower into boiling water covering jars by 1–2 in. Start timing when water returns to a full boil. Add 5 min for 1,001–3,000 ft elevation.</li><li>Remove, cool 12–24 hours undisturbed. Lids should pop down. Remove rings, label and date.</li></ol>
<h2>Pressure canning</h2><p>Use a real pressure canner (not an Instant Pot). Typical: 10 lb pressure (weighted gauge) or 11 lb (dial gauge) at sea level to 1,000 ft; increase per instructions at higher elevation. Examples: green beans 20 min pints/25 min quarts; dry beans (soaked) 75/90 min; chicken/meat 75/90 min.</p>
<p>Off‑grid: canners work on propane burners, wood stoves, or a good fire with steady heat — keep pressure steady.</p>
<h2>Storage</h2><p>Cool, dark place. Use within 1–2 years for quality. Discard bulging lids, leaks, spurting, mold or off smells. Boiling home‑canned low‑acid food 10 minutes before eating adds a safety margin.</p>` },
    { id: 'drying', title: 'Drying & dehydrating', sum: 'Sun drying, jerky, fruit leather, dried vegetables', tags: ['drying', 'dehydrating', 'jerky', 'fruit leather', 'sun drying', 'dehydrator'], body: `
<p>Removing water stops bacteria and mold. Southeast humidity makes sun drying slow — use a solar dehydrator (screened box with a black collector and vents), an oven at its lowest setting with the door cracked, or a car dashboard on hot days (covered with screen/cheesecloth).</p>
<ul><li>Slice evenly ¼ in thick. Pretreat light fruits in lemon juice or ascorbic acid to prevent browning.</li><li>Fruits: dry until leathery, no moisture when squeezed (135°F, 6–12 h). Condition in a jar a week, shaking daily; if condensation appears, dry more.</li><li>Vegetables: blanch most first (steam 3–5 min), then dry until brittle (125°F).</li><li>Herbs: hang bunches upside down in a dry shady place.</li><li><b>Fruit leather:</b> purée fruit (add honey), spread ⅛ in thick on lined trays, dry until not sticky.</li></ul>
<h2>Jerky (safe method)</h2><ol class="steps"><li>Use lean meat (venison, beef round). Trim all fat (fat goes rancid). Freezing partially makes slicing easier.</li><li>Slice ¼ in thick <b>with the grain</b> for chewy, against it for tender.</li><li>Marinate (salt, soy sauce, pepper, garlic) overnight in the fridge.</li><li><b>Heat to 160°F</b> (165°F poultry) first — steam or bake in the marinade, or oven at 275°F for 10 min — to kill bacteria (USDA). Wild game should be heated this way to kill parasites.</li><li>Dry at 130–145°F until it cracks but doesn't break when bent (4–12 h).</li><li>Store airtight; 1–2 months at room temp, longer frozen.</li></ol>
<h2>Pemmican</h2><p>Dried meat pounded to powder + equal weight rendered fat (tallow) + optional dried berries. Pack into bags or molds. Extremely calorie dense; keeps months to years cool.</p>` },
    { id: 'smoking-salting', title: 'Smoking, salting, curing & fermenting', sum: 'Salt cure, smokehouse, sauerkraut, pickles, eggs', tags: ['smoking', 'salt', 'curing', 'brine', 'fermenting', 'sauerkraut', 'pickles', 'eggs', 'water glassing'], body: `
<h2>Salt curing</h2><p>Pack meat or fish in salt (pure, non‑iodized; about 1 lb per 10 lb meat plus extra to bury it) for a few days, then hang in a cool, dry, airy place. Country ham and salt pork are made this way in cold weather (below 40°F — winter in the Southeast). Commercial curing salt (Prague powder) with nitrite prevents botulism — follow recipe amounts exactly. Soak salted meat in water before cooking.</p>
<h2>Smoking</h2><ul><li><b>Cold smoking</b> (below 90°F) flavors but doesn't cook — use only on properly cured meat or fish.</li><li><b>Hot smoking</b> (165°F+ internal) cooks and preserves for a short time (days–weeks). Fish: brine 1 cup salt per gallon water for 1–2 hours, air dry, smoke until flaky.</li><li>Use hardwoods: hickory, oak, pecan, fruitwoods. <b>Never pine or other resinous wood</b> (bitter, sooty).</li><li>Build a simple smoker from a trash can or a teepee of poles covered with a tarp/blanket over a smoldering fire pit with a tunnel trench.</li></ul>
<h2>Fermentation</h2><p><b>Sauerkraut:</b> shred cabbage, mix with 2% salt by weight (about 1 tbsp per 1.5 lb), massage until juicy, pack into a jar so liquid covers it, weigh it down, ferment at room temp 1–4 weeks. Same method for fermented greens, carrots, peppers. <b>Brine pickles:</b> cucumbers in 3.5–5% salt brine (2–3 tbsp salt per quart water) with garlic and dill, 1–3 weeks. Keep below the brine; skim surface scum.</p>
<h2>Eggs</h2><p><b>Water glassing:</b> clean, unwashed, uncracked fresh eggs submerged in a solution of 1 oz (by weight) pickling lime per quart of water, stored cool — keep 8–12 months. Coating eggs in mineral oil also extends storage.</p>` },
    { id: 'root-cellar', title: 'Root cellaring & cool storage', sum: 'Storing vegetables without refrigeration', tags: ['root cellar', 'storage', 'potatoes', 'sweet potatoes', 'apples', 'clamp', 'zeer pot', 'evaporative cooler'], body: `
<div class="tbl"><table><tr><th>Crop</th><th>Conditions</th><th>Keeps</th></tr>
<tr><td>Sweet potatoes (cured)</td><td>55–60°F, moderate humidity — <b>never below 50°F</b></td><td>6–10 months</td></tr>
<tr><td>Irish potatoes</td><td>40–50°F, dark, humid</td><td>4–6 months</td></tr>
<tr><td>Winter squash, pumpkins</td><td>50–55°F, dry</td><td>2–6 months</td></tr>
<tr><td>Onions, garlic (cured)</td><td>32–50°F, dry, airy (mesh bags)</td><td>4–8 months</td></tr>
<tr><td>Carrots, beets, turnips</td><td>32–40°F, very humid (in damp sand)</td><td>3–5 months</td></tr>
<tr><td>Apples, pears</td><td>32–40°F, humid; store away from potatoes (ethylene)</td><td>2–6 months</td></tr>
<tr><td>Cabbage</td><td>32–40°F, humid</td><td>3–4 months</td></tr></table></div>
<p>The Southeast's warm winters make true root cellars harder; an insulated buried container (a clean plastic barrel or old chest freezer buried on its side in a north‑facing slope), a basement, or a crawlspace corner can work. A "clamp" — vegetables layered with straw and covered with soil — works for roots outdoors.</p>
<h2>Evaporative cooling (zeer pot)</h2><p>Put a smaller clay pot inside a larger one, fill the gap with wet sand, cover the top with a wet cloth, set in shade with a breeze. Keeps vegetables 15–20°F cooler than air. Works best in dry air; still helpful in the Southeast. A wet towel draped over a crate in a breeze does similar.</p>` }
  ]
}
  );
})();
